export class AutoFixEngine{analyze(imageData){const{data,width,height}=imageData,step=Math.max(1,Math.floor(Math.sqrt(width*height/90000)));let count=0,sum=0,sumSq=0,sat=0,shadow=0,highlight=0,noise=0,edge=0,skin=0;for(let y=1;y<height-1;y+=step)for(let x=1;x<width-1;x+=step){const i=(y*width+x)*4,r=data[i],g=data[i+1],b=data[i+2],l=r*.2126+g*.7152+b*.0722,max=Math.max(r,g,b),min=Math.min(r,g,b);sum+=l;sumSq+=l*l;sat+=max?(max-min)/max:0;if(l<18)shadow++;if(l>238)highlight++;if(isSkin(r,g,b))skin++;const left=lumaAt(data,i-4),right=lumaAt(data,i+4),top=lumaAt(data,i-width*4),bottom=lumaAt(data,i+width*4),gradient=Math.abs(right-left)+Math.abs(bottom-top);edge+=gradient;if(gradient<18)noise+=Math.abs(4*l-left-right-top-bottom);count++}const mean=sum/Math.max(1,count),dev=Math.sqrt(Math.max(0,sumSq/Math.max(1,count)-mean*mean)),metrics={exposure:mean/255,contrast:dev/90,saturation:sat/Math.max(1,count),noise:Math.min(1,noise/Math.max(1,count)/18),detail:Math.min(1,edge/Math.max(1,count)/62),clippedShadows:shadow/Math.max(1,count),clippedHighlights:highlight/Math.max(1,count),skinPresence:skin/Math.max(1,count)};return{metrics,effects:recommend(metrics),summary:summarize(metrics)}}}
export function recommend(m){const dark=m.exposure<.38?Math.min(.18,(.42-m.exposure)*.55):0,bright=m.exposure>.7?-Math.min(.12,(m.exposure-.67)*.45):0;return{brightness:round(dark+bright),contrast:round(Math.max(.9,Math.min(1.22,1.08-(m.contrast-.5)*.18))),saturation:round(Math.max(.92,Math.min(1.13,1.06-(m.saturation-.3)*.2))),vibrance:round(m.saturation<.3?.2:.08),sharpenAmount:round(m.detail<.35?.72:.4),sharpenThreshold:round(m.noise>.35?.05:.025),highPassAmount:round(m.detail<.28?.25:.08),denoiseAmount:round(Math.max(.08,Math.min(.56,m.noise*.65))),detailAmount:round(Math.max(.12,Math.min(.62,(1-m.detail)*.58))),portraitSmooth:round(m.skinPresence>.08?Math.max(.08,Math.min(.28,m.noise*.25+.08)):0),temperature:0,gamma:1}}
function summarize(m){const n=[];if(m.exposure<.36)n.push('رفع الإضاءة المتوسطة');else if(m.exposure>.72)n.push('حماية المناطق الساطعة');if(m.noise>.3)n.push('تقليل ضوضاء متوازن');if(m.detail<.38)n.push('استعادة الحواف والتفاصيل');if(m.skinPresence>.08)n.push('تنعيم البشرة مع حماية العين والشفاه');if(!n.length)n.push('الفيديو متوازن؛ تحسين نظيف خفيف');return n.join(' · ')}
function isSkin(r,g,b){return r>95&&g>40&&b>20&&Math.max(r,g,b)-Math.min(r,g,b)>15&&Math.abs(r-g)>15&&r>g&&r>b}function lumaAt(d,i){return d[i]*.2126+d[i+1]*.7152+d[i+2]*.0722}function round(v){return Math.round(v*100)/100}
