const SPEED={LOW:18e6,MEDIUM:42e6,HIGH:85e6,ULTRA:150e6};
export class RenderEstimator{constructor(){this.startedAt=0}estimate({duration,sourceWidth,sourceHeight,targetWidth,targetHeight,sourceFps=30,targetFps=30,effects={},ai={},tier='LOW'}){if(!Number.isFinite(duration)||duration<=0)return null;const frames=Math.max(1,Math.ceil(duration*Math.max(sourceFps,targetFps))),pixels=Math.max(sourceWidth*sourceHeight,targetWidth*targetHeight);let cost=1+(effects.denoiseAmount||0)*.8+(effects.temporalDenoise||0)*.34+(effects.antiFlicker||0)*.08+(effects.sharpenAmount||0)*.18+(effects.detailAmount||0)*.28+(effects.portraitSmooth||0)*1.1+(effects.dehaze||0)*.08+(effects.grain||0)*.04;if(ai.upscale)cost*=8.5;if(ai.rife)cost*=2.8;if(ai.face)cost*=4.2;return{seconds:Math.max(5,frames*pixels*cost/(SPEED[tier]||SPEED.LOW)+Math.max(4,duration*.08)),frames,outputPixels:pixels,confidence:ai.upscale||ai.rife||ai.face?'تقريبي حسب النموذج':'تقدير حسب الجهاز'}}start(){this.startedAt=performance.now()}live(progress){if(!this.startedAt||progress<=0)return null;const elapsed=(performance.now()-this.startedAt)/1000,effective=Math.max(.005,progress);return{elapsed,remaining:Math.max(0,elapsed/effective*(1-effective)),speed:progress/Math.max(.001,elapsed)}}}
export function formatDuration(seconds){if(!Number.isFinite(seconds))return'—';const v=Math.max(0,Math.round(seconds)),h=Math.floor(v/3600),m=Math.floor(v%3600/60),s=v%60;if(h)return`${h} س ${m} د`;if(m)return`${m} د ${s} ث`;return`${s} ثانية`}
